import{_ as s,o as t,c as a,a2 as r}from"./chunks/framework.Zh78JZbW.js";const m=JSON.parse('{"title":"Installer Kodus","description":"","frontmatter":{},"headers":[],"relativePath":"guide/installer.md","filePath":"guide/installer.md"}'),o={name:"guide/installer.md"};function i(n,e,l,u,d,c){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="installer-kodus" tabindex="-1">Installer Kodus <a class="header-anchor" href="#installer-kodus" aria-label="Permalink to &quot;Installer Kodus&quot;">​</a></h1><p>Tout se télécharge sur la <a href="https://github.com/Dusko01/kodus-releases/releases/latest" target="_blank" rel="noreferrer">page des versions</a>, dans la partie <strong>Assets</strong>.</p><table tabindex="0"><thead><tr><th>Fichier</th><th>Pour qui</th></tr></thead><tbody><tr><td><code>Kodus-Setup-….exe</code></td><td>Windows, le plus simple (mises à jour automatiques)</td></tr><tr><td><code>Kodus-…-portable.zip</code></td><td>Windows, si l&#39;installeur est bloqué</td></tr><tr><td><code>Kodus-…-mac-arm64.dmg</code></td><td>Mac avec puce Apple (M1, M2, M3…)</td></tr><tr><td><code>Kodus-…-mac-x64.dmg</code></td><td>Mac avec processeur Intel</td></tr></tbody></table><h2 id="sur-windows" tabindex="-1">Sur Windows <a class="header-anchor" href="#sur-windows" aria-label="Permalink to &quot;Sur Windows&quot;">​</a></h2><ol><li>Télécharge <code>Kodus-Setup-….exe</code> et lance-le.</li><li>Windows affiche un écran bleu « Windows a protégé votre ordinateur ». Pas de panique : c&#39;est parce que Kodus n&#39;est pas signé (ça coûte cher), pas parce qu&#39;il est dangereux. Clique sur <strong>Informations complémentaires</strong>, puis <strong>Exécuter quand même</strong>.</li><li>Suis l&#39;installation. Kodus se mettra ensuite à jour tout seul.</li></ol><h2 id="si-windows-bloque-sans-bouton-«-executer-quand-meme-»" tabindex="-1">Si Windows bloque sans bouton « Exécuter quand même » <a class="header-anchor" href="#si-windows-bloque-sans-bouton-«-executer-quand-meme-»" aria-label="Permalink to &quot;Si Windows bloque sans bouton « Exécuter quand même »&quot;">​</a></h2><p>C&#39;est la « protection intelligente des applications » de Windows 11. Deux solutions :</p><h3 id="a-utiliser-la-version-portable-pas-de-mises-a-jour-automatiques" tabindex="-1">A) Utiliser la version portable (pas de mises à jour automatiques) <a class="header-anchor" href="#a-utiliser-la-version-portable-pas-de-mises-a-jour-automatiques" aria-label="Permalink to &quot;A) Utiliser la version portable (pas de mises à jour automatiques)&quot;">​</a></h3><ol><li>Télécharge <code>Kodus-…-portable.zip</code>.</li><li>Clic droit dessus → <strong>Extraire tout</strong>, et range le dossier où tu veux (pas dans Téléchargements, sinon tu risques de le supprimer par erreur).</li><li>Lance <code>Kodus.exe</code> dans ce dossier. Tu peux faire un clic droit → <strong>Afficher d&#39;autres options</strong> → <strong>Envoyer vers</strong> → <strong>Bureau (créer un raccourci)</strong>.</li></ol><h3 id="b-desactiver-la-protection-temporairement-a-faire-une-seule-fois" tabindex="-1">B) Désactiver la protection temporairement (à faire une seule fois) <a class="header-anchor" href="#b-desactiver-la-protection-temporairement-a-faire-une-seule-fois" aria-label="Permalink to &quot;B) Désactiver la protection temporairement (à faire une seule fois)&quot;">​</a></h3><ol><li>Ouvre les <strong>Paramètres</strong> de Windows (touches Windows + I) → <strong>Confidentialité et sécurité</strong> → <strong>Sécurité Windows</strong>.</li><li>Clique <strong>Ouvrir Sécurité Windows</strong>.</li><li>Va dans <strong>Contrôle des applications et du navigateur</strong> → <strong>Paramètres du contrôle intelligent des applications</strong>.</li><li>Choisis <strong>Désactivé</strong>.</li><li>Double-clique sur <code>Kodus-Setup-….exe</code> pour lancer l&#39;installeur.</li><li>Sur l&#39;écran bleu « Windows a protégé votre ordinateur », clique <strong>Informations complémentaires</strong> puis <strong>Exécuter quand même</strong>, et suis l&#39;installation.</li><li>Une fois Kodus installé, retourne au même endroit et <strong>réactive</strong> la protection.</li></ol><h2 id="sur-mac" tabindex="-1">Sur Mac <a class="header-anchor" href="#sur-mac" aria-label="Permalink to &quot;Sur Mac&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">macOS 13 (Ventura) ou plus récent</p><p>Kodus demande macOS 13 minimum, ce qui correspond en gros aux Mac de 2017 et après. Pour vérifier : menu Pomme → <strong>À propos de ce Mac</strong>.</p></div><ol><li>Menu Pomme → <strong>À propos de ce Mac</strong> : si tu vois « Puce Apple M… », prends <code>Kodus-…-mac-arm64.dmg</code>, sinon <code>Kodus-…-mac-x64.dmg</code>.</li><li>Ouvre le <code>.dmg</code> et glisse Kodus dans <strong>Applications</strong>.</li><li>Au premier lancement, macOS refuse de l&#39;ouvrir. Clique <strong>OK</strong>, puis va dans <strong>Réglages Système</strong> → <strong>Confidentialité et sécurité</strong>, et tout en bas clique <strong>Ouvrir quand même</strong>. Une seule fois.</li><li>Si macOS dit que Kodus est « endommagé » (il ne l&#39;est pas), ouvre l&#39;app <strong>Terminal</strong>, colle cette ligne et appuie sur Entrée :</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xattr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -dr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.apple.quarantine</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /Applications/Kodus.app</span></span></code></pre></div><p>Ensuite : <a href="./premier-lancement">Premier lancement</a>.</p>',16)])])}const g=s(o,[["render",i]]);export{m as __pageData,g as default};
